// Current editorial section forecast; official Hakone entries have not been announced.
(() => {
 const db=window.hakoneCurrentOrders20261101;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function html(){
  const order=typeof hakoneScoreRows20261101!=='undefined'?hakoneScoreRows20261101:Object.keys(db.teams).map(team=>({team}));
  return `<section class="hakone-ideal-orders hakone-current-orders"><h2>現時点の区間予想 · 出場20校</h2><p>11月1日更新。全日本・出雲・箱根予選会の走者と既存DBを踏まえた、登録前の理想オーダーです。大学名をタップすると往路・復路の10人、配置理由、直近の成績を確認できます。</p>
  <p class="notice">公式エントリーではありません。山は経験者を優先し、同区間の経験が確認できない候補は「山適性未確認」と表示。平地の好記録だけで山の適性を断定せず、留学生は各大学1人までにしています。</p>
  <div class="hakone-ideal-team-list">${order.map(({team},index)=>{
   const plan=db.teams[team];if(!plan)return '';
   const [icon,color,ink]=forecastTeamVisual20261012(team);
   return `<details class="hakone-ideal-team" data-current-hakone-team="${esc(team)}" style="--forecast-team-color:${color};--forecast-team-ink:${ink}"><summary><span class="forecast-team-identity"><span class="forecast-team-icon" aria-hidden="true">${esc(icon)}</span><strong>${esc(team)}</strong></span><span class="hakone-ideal-open-label">予想${index+1}位 · 全10区 ▾</span></summary><div class="hakone-ideal-body">${[0,1].map(day=>`<h3>${day===0?'往路 1〜5区':'復路 6〜10区'}</h3><div class="hakone-ideal-grid">${plan.runners.slice(day*5,day*5+5).map((p,j)=>{
    const i=day*5+j,sec=i+1,course=hakoneIdealSections20261012[i],hill=i===4||i===5;
    return `<article class="hakone-ideal-section ${hill?'is-mountain':''}" data-current-hakone-section="${sec}"><header><strong>${sec}区 ${hill?(i===4?'山上り':'山下り'):''}</strong><span>${course[0].toFixed(1)}km</span></header><small class="hakone-ideal-course">${esc(course[1])}</small><h4>${esc(p.name)}<small>${p.grade?esc(p.grade)+'年':'学年確認中'}</small></h4>${hill?`<span class="hakone-ideal-evidence">${p.mountainConfirmed?'前年同区間の経験あり':'山適性未確認・暫定候補'}</span>`:''}<p>${esc(p.reason)}</p><dl class="hakone-ideal-pb"><div><dt>10000m PB（DB）</dt><dd>${esc(p.pb10000)}</dd></div><div><dt>ハーフ PB（DB）</dt><dd>${esc(p.half)}</dd></div></dl><div class="hakone-ideal-records">${p.recent.map(text=>`<p>${esc(text)}</p>`).join('')}${p.previous.map(r=>`<p>2026箱根 ${r.section}区 ${esc(r.rank)}位 · ${esc(r.time)}</p>`).join('')}${!p.recent.length&&!p.previous.length?'<p>直近の駅伝・予選会の出走記録は収録なし</p>':''}</div></article>`;
   }).join('')}</div>`).join('')}<p class="hakone-ideal-alternative"><strong>代替案・配置の迷い</strong><br>${esc(plan.alternative)}</p></div></details>`;
  }).join('')}</div><details class="forecast-course-guide"><summary>箱根10区間の特徴を見る</summary><div class="hakone-ideal-grid">${hakoneIdealSections20261012.map((c,i)=>`<article class="hakone-ideal-section"><h3>${i+1}区 · ${c[0].toFixed(1)}km</h3><small>${esc(c[1])}</small><p>${esc(c[2])}</p></article>`).join('')}</div></details>
  <p class="forecast-sources"><a href="https://www.hakone-ekiden.jp/record/tournament-section.php?section=5&tn=106" target="_blank" rel="noopener">2026箱根区間記録</a> ／ <a href="https://www.kgrr.org/files/competition/147/40/103yose_kozin.PDF" target="_blank" rel="noopener">2026予選会公式個人成績</a> ／ <a href="https://www.nikkansports.com/sports/athletics/news/202610290000242.html" target="_blank" rel="noopener">全日本区間結果</a> ／ <a href="https://www.izumo-ekiden.jp/assets/pdf/record2026.pdf" target="_blank" rel="noopener">出雲公式結果</a></p></section>`;
 }
 const previous=templates.prediction;
 const marker='<details class="forecast-course-guide"><summary>10月12日時点のシード10校・区間予想（保存版）</summary>';
 templates.prediction=function(){const base=previous();return base.includes(marker)?base.replace(marker,html()+marker):base.replace(/<\/section>\s*$/,html()+'</section>');};
 if(location.hash.replace('#','')==='prediction')render('prediction');
})();
